USE DATABASE SELLER_SCORECARD_DB; USE WAREHOUSE SCORECARD_WH; USE ROLE SCORECARD_ANALYST_ROLE;
SELECT seller_id,seller_state,SUM(orders) total_orders,SUM(revenue) total_revenue,SUM(late_orders) total_late,ROUND(100.0*SUM(late_orders)/NULLIF(SUM(orders),0),2) late_rate_pct,ROUND(AVG(avg_review_score),2) avg_review_score FROM ANALYTICS.GOLD_SELLER_MONTH GROUP BY seller_id,seller_state ORDER BY late_rate_pct DESC;
SELECT seller_id,month,orders,late_orders,ROUND(100.0*late_orders/NULLIF(orders,0),2) month_late_rate_pct FROM ANALYTICS.GOLD_SELLER_MONTH ORDER BY seller_id,month;
WITH pre AS (SELECT seller_id,SUM(late_orders) late,SUM(orders) ord FROM ANALYTICS.GOLD_SELLER_MONTH WHERE month<'2025-04-01' GROUP BY seller_id), post AS (SELECT seller_id,SUM(late_orders) late,SUM(orders) ord FROM ANALYTICS.GOLD_SELLER_MONTH WHERE month>='2025-04-01' GROUP BY seller_id)
SELECT pre.seller_id,ROUND(100.0*pre.late/NULLIF(pre.ord,0),2) pre_apr_late_pct,ROUND(100.0*post.late/NULLIF(post.ord,0),2) apr_onward_late_pct,ROUND((100.0*post.late/NULLIF(post.ord,0))/NULLIF(100.0*pre.late/NULLIF(pre.ord,0),0),2) escalation_factor FROM pre JOIN post USING(seller_id) ORDER BY escalation_factor DESC LIMIT 10;
SELECT seller_state,COUNT(DISTINCT seller_id) sellers,SUM(orders) orders,SUM(revenue) revenue,ROUND(100.0*SUM(late_orders)/NULLIF(SUM(orders),0),2) late_rate_pct FROM ANALYTICS.GOLD_SELLER_MONTH GROUP BY seller_state ORDER BY revenue DESC;